        "type": "VARCHAR"
      },
      "team_member_role": {
        "comment": "Effective team member role filter; omission uses all roles. Child-team members can be inherited. Allowed values: [\"member\", \"maintainer\", \"all\"]. Validated before retrieval.",
        "default": null,
        "example": "maintainer",
        "nullable": true,
        "type": "VARCHAR"
      },
      "team_member_user": {
        "comment": "Account login for an exact team membership or membership-check observation.",
        "default": null,
        "example": "membership-alice",
        "non_empty": true,
        "nullable": true,
        "type": "VARCHAR"
      },
      "team_membership_check": {
        "comment": "Select the pinned legacy 204/404 membership observation, rather than a membership-object record. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "team_numeric_id": {
        "comment": "Exact stable team identity through pinned legacy numeric routes; GitHub marks these routes as closing down. Prefer organization plus team_slug where available.",
        "default": null,
        "example": 3201,
        "minimum": 1,
        "nullable": true,
        "type": "BIGINT"
      },
      "team_repository_check": {
        "comment": "Select a team/repository visibility check: 404 is unconfirmed access and can reflect insufficient caller permission. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "team_repository_permission": {
        "comment": "Select an exact typed team/repository permission object using the pinned repository media representation. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "team_slug": {
        "comment": "Slug of one team; requires organization.",
        "default": null,
        "example": "core",
        "non_empty": true,
        "nullable": true,
        "type": "VARCHAR"
      },
      "traffic_granularity": {
        "comment": "Traffic bucket aggregation: day or week. Omission means day. Both retain the current rolling 14-day response window. Allowed values: [\"day\", \"week\"]. Validated before retrieval.",
        "default": null,
        "example": "day",
        "nullable": true,
        "type": "VARCHAR"
      },
      "tree_sha": {
        "comment": "Exact Git tree SHA; returns direct child entries only.",
        "default": null,
        "example": "dddddddddddddddddddddddddddddddddddddddd",
        "non_empty": true,
        "nullable": true,
        "type": "VARCHAR"
      },
      "user": {
        "comment": "One personal GitHub user login, including work in repositories owned by other accounts.",
        "default": null,
        "example": "octocat",
        "non_empty": true,
        "nullable": true,
        "type": "VARCHAR"
      },
      "user_account_id": {
        "comment": "Stable numeric account ID for the canonical personal User-only population. Organization and Bot accounts are outside that population.",
        "default": null,
        "example": 2601,
        "minimum": 1,
        "nullable": true,
        "type": "BIGINT"
      },
      "user_context_subject_id": {
        "comment": "Opaque hovercard context subject ID; requires user_context_subject_type. This is not an issue/PR number.",
        "default": null,
        "example": "123",
        "non_empty": true,
        "nullable": true,
        "type": "VARCHAR"
      },
      "user_context_subject_type": {
        "comment": "Hovercard context subject type; requires user_context_subject_id. The subject is distinct from the user being described. Allowed values: [\"organization\", \"repository\", \"issue\", \"pull_request\"]. Validated before retrieval.",
        "default": null,
        "example": "repository",
        "nullable": true,
        "type": "VARCHAR"
      },
      "user_directory": {
        "comment": "Explicitly enumerate the global public account directory, retaining only personal User accounts and hydrating canonical profiles. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "user_email_population": {
        "comment": "Select all email addresses visible to the authenticated account, or only its public addresses. Allowed values: [\"all\", \"public\"]. Validated before retrieval.",
        "default": null,
        "example": "all",
        "nullable": true,
        "type": "VARCHAR"
      },
      "user_since_id": {
        "comment": "Optional exclusive numeric account-ID cursor for global directory retrieval; results cover only accounts after this ID.",
        "default": null,
        "example": 2600,
        "minimum": 0,
        "nullable": true,
        "type": "BIGINT"
      },
      "users": {
        "comment": "Personal-user cohort. Supply users or user; an empty cohort returns zero counts. Each login must be nonempty and unique ignoring case.",
        "default": null,
        "example": [
          {
            "login": "octocat"
          },
          {
            "login": "hubot"
          }
        ],
        "nullable": true,
        "type": "STRUCT(\"login\" VARCHAR)[]"
      },
      "viewer_issues": {
        "comment": "Select /issues across repositories visible to the authenticated user; requires a token. Must be true. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "viewer_member_issues": {
