        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "viewer_organization_issues": {
        "comment": "Select /orgs/{org}/issues for the authenticated user in the selected organization. Must be true. Allowed values: [true]. Validated before retrieval.",
        "default": null,
        "example": true,
        "nullable": true,
        "type": "BOOLEAN"
      },
      "workflow_id": {
        "comment": "Numeric workflow identity; distinct from the mutable workflow name.",
        "default": null,
        "example": 1,
        "minimum": 1,
        "nullable": true,
        "type": "BIGINT"
      },
      "zip_archive_ref": {
        "comment": "zip_archive_ref",
        "default": null,
        "example": "main",
